function createWeights(overrides) {
  const base = {
    functionality: 10,
    code_quality: 10,
    security: 15,
    performance: 10,
    architecture: 10,
    database: 8,
    reliability: 10,
    compatibility: 5,
    usability: 5,
    installation: 5,
    privacy: 7,
    documentation: 5
  };
  const merged = { ...base, ...overrides };
  const total = Object.values(merged).reduce((acc, v) => acc + v, 0);
  if (total <= 0) return base;
  const normalized = {};
  let sum = 0;
  ALL_12_CATEGORIES.forEach((cat, idx) => {
    if (idx === ALL_12_CATEGORIES.length - 1) {
      normalized[cat] = Math.max(0, 100 - sum);
    } else {
      const val = Math.round(merged[cat] / total * 100);
      normalized[cat] = val;
      sum += val;
    }
  });
  return normalized;
}
